(function () {
'use strict';
var U = window.U;
function v(id) { return U.numInput(document.getElementById(id)); }
function row(k, val) { return '<div class="result-detail-row"><dt>' + k + '</dt><dd>' + val + '</dd></div>'; }
var sections = { single: '.disc-single', double: '.disc-double', reduce: '.disc-reduce' };
function toggleMode(mode) {
Object.keys(sections).forEach(function (k) {
document.querySelector(sections[k]).hidden = k !== mode;
});
}
function calc() {
var price = v('disc-price');
if (!Number.isFinite(price) || price <= 0) { alert('请输入有效原价'); return; }
var mode = document.getElementById('disc-mode').value;
var final, detail = [];
if (mode === 'single') {
var d = v('disc-d1'); if (!Number.isFinite(d)) { alert('请输入折扣'); return; }
final = price * d / 10;
detail.push(row('折扣', d + ' 折'));
} else if (mode === 'double') {
var d1 = v('disc-d1b'), d2 = v('disc-d2');
if (!Number.isFinite(d1) || !Number.isFinite(d2)) { alert('请输入两道折扣'); return; }
final = price * d1 / 10 * d2 / 10;
detail.push(row('折上折', d1 + ' 折 × ' + d2 + ' 折'));
} else {
var full = v('disc-full'), minus = v('disc-minus');
if (!Number.isFinite(full) || full <= 0 || !Number.isFinite(minus)) { alert('请输入满减门槛与减免'); return; }
var times = Math.floor(price / full);
final = price - times * minus;
detail.push(row('满减', '每满 ' + full + ' 减 ' + minus + '（' + times + ' 次）'));
}
if (final < 0) final = 0;
var save = price - final;
var eq = price > 0 ? (final / price * 10).toFixed(2) : '0';
document.getElementById('disc-final').textContent = U.money(final);
document.getElementById('disc-save').textContent = U.money(save);
detail.push(row('相当于', eq + ' 折'));
document.getElementById('disc-detail').innerHTML = detail.join('');
document.getElementById('disc-result').hidden = false;
U.track('calc_result', { tool: 'discount', mode: mode });
}
function init() {
var form = document.getElementById('discForm');
if (!form) return;
var sel = document.getElementById('disc-mode');
sel.addEventListener('change', function () { toggleMode(sel.value); });
toggleMode(sel.value);
form.addEventListener('submit', function (e) { e.preventDefault(); calc(); });
document.getElementById('disc-clear').addEventListener('click', function () { form.reset(); toggleMode('single'); document.getElementById('disc-result').hidden = true; });
}
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
})();
